package android.preference;import android.content.Context;public class Preference{public android.content.Intent intent;public void setIntent(android.content.Intent i){intent=i;}String key;CharSequence title,summary;int order;public OnPreferenceChangeListener change;public OnPreferenceClickListener click;public interface OnPreferenceChangeListener{boolean onPreferenceChange(Preference p,Object v);}public interface OnPreferenceClickListener{boolean onPreferenceClick(Preference p);}public Preference(Context c){}public String getKey(){return key;}public void setKey(String k){key=k;}public void setTitle(CharSequence t){title=t;}public CharSequence getTitle(){return title;}public void setSummary(CharSequence s){summary=s;}public CharSequence getSummary(){return summary;}public void setOrder(int n){order=n;}public int getOrder(){return order;}public void setOnPreferenceChangeListener(OnPreferenceChangeListener l){change=l;}public void setOnPreferenceClickListener(OnPreferenceClickListener l){click=l;}}
